def divs(v):
    return [x for x in range(1,v) if v%x==0]
@functools.lru_cache(None)
def win(state):
    # state: sorted tuple; returns True if player to move wins
    for i,v in enumerate(state):
        if i>0 and state[i-1]==v: continue
        for x in divs(v):
            ns=tuple(sorted(state[:i]+(x,)+state[i+1:]))
            if not win(ns): return True
    return False
