import numpy as np
P=998244353
def wht(a,mod):
    n=len(a); h=1
    while h<n:
        a=a.reshape(-1,2,h)
        x=a[:,0,:]; y=a[:,1,:]
        if mod: a=np.stack([(x+y)%P,(x-y)%P],axis=1).reshape(-1)
        else: a=np.stack([x+y,x-y],axis=1).reshape(-1)
        h*=2
    return a
