from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        bymax = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            lo, hi = min(a, b), max(a, b)
            bymax[hi].append((lo, i))
        m = len(conflictingPairs)
        delta = [0] * m
        t1v, t1i, t2v = 0, -1, 0
        base = 0
        for r in range(1, n + 1):
            for v, i in bymax[r]:
                if v > t1v:
                    t2v = t1v
                    t1v, t1i = v, i
                elif v > t2v:
                    t2v = v
            base += r - t1v
            if t1i >= 0:
                delta[t1i] += t1v - t2v
        return base + (max(delta) if m else 0)

