import sys
def main():
    data=sys.stdin.buffer.read().split()
    p=0
    n=int(data[p]); m=int(data[p+1]); q=int(data[p+2]); p+=3
    INF=10**18
    edges=[]
    for _ in range(m):
        a=int(data[p])-1; b=int(data[p+1])-1; c=int(data[p+2]); p+=3
        edges.append((a,b,c))
    queries=[]
    closed=[False]*m
    for _ in range(q):
        t=data[p]
        if t==b'1':
            i=int(data[p+1])-1; p+=2
            closed[i]=True
            queries.append((1,i))
        else:
            x=int(data[p+1])-1; y=int(data[p+2])-1; p+=3
            queries.append((2,x,y))
    try:
        import numpy as np
        USE_NP=True
    except Exception:
        USE_NP=False
    if USE_NP:
        D=np.full((n,n),INF,dtype=np.int64)
        np.fill_diagonal(D,0)
        for i,(a,b,c) in enumerate(edges):
            if not closed[i]:
                if c<D[a,b]:
                    D[a,b]=c; D[b,a]=c
        for k in range(n):
            D=np.minimum(D,D[:,k:k+1]+D[k:k+1,:])
        ans=[]
        for qq in reversed(queries):
            if qq[0]==2:
                d=int(D[qq[1],qq[2]])
                ans.append(d if d<INF else -1)
            else:
                a,b,c=edges[qq[1]]
                A=D[:,a].copy(); B=D[:,b].copy()
                Ru=D[a,:].copy(); Rv=D[b,:].copy()
                D=np.minimum(D,np.minimum((A+c)[:,None]+Rv[None,:],(B+c)[:,None]+Ru[None,:]))
                np.minimum(D,INF,out=D)
    else:
        D=[[INF]*n for _ in range(n)]
        for i in range(n): D[i][i]=0
        for i,(a,b,c) in enumerate(edges):
            if not closed[i]:
                if c<D[a][b]:
                    D[a][b]=c; D[b][a]=c
        for k in range(n):
            rk=D[k]
            for i in range(n):
                dik=D[i][k]
                if dik>=INF: continue
                D[i]=list(map(min,D[i],map(dik.__add__,rk)))
        ans=[]
        for qq in reversed(queries):
            if qq[0]==2:
                d=D[qq[1]][qq[2]]
                ans.append(d if d<INF else -1)
            else:
                a,b,c=edges[qq[1]]
                Ru=D[a][:]; Rv=D[b][:]
                P=[c+r for r in Rv]; Q=[c+r for r in Ru]
                for i in range(n):
                    A=Ru[i]; B=Rv[i]
                    if A>=INF and B>=INF: continue
                    D[i]=list(map(min,D[i],map(A.__add__,P),map(B.__add__,Q)))
    ans.reverse()
    sys.stdout.write("\n".join(map(str,ans))+("\n" if ans else ""))
