import sys

def solve(N, A):
    A = [0] + A
    L = [0]*(N+1); L[0] = -10**9; seen = set()
    for i in range(1, N+1):
        seen.add(A[i]); L[i] = len(seen)
    R = [0]*(N+2); seen = set()
    for j in range(N, 0, -1):
        seen.add(A[j]); R[j] = len(seen)
    par = list(range(N+3))
    def find(x):
        r = x
        while par[r] != r:
            r = par[r]
        while par[x] != r:
            par[x], x = r, par[x]
        return r
    prv = [0]*(N+2); diff = [0]*(N+2)
    tp = 0; topval = 0; M = 0
    last = [0]*(N+1)
    best = -10**18
    for j in range(1, N+1):
        v = L[j-1]
        while tp and topval <= v:
            if prv[tp] == 0:
                tp = 0
                break
            topval += diff[tp]
            q = tp; tp = prv[q]; par[q] = q+1
        if tp:
            diff[j] = topval - v
            prv[j] = tp
        else:
            prv[j] = 0
            M = v
        tp = j; topval = v
        p = last[A[j]]; last[A[j]] = j
        k = find(p+1)
        topval += 1
        if prv[k] == 0:
            M += 1
        else:
            diff[k] -= 1
            if diff[k] == 0:
                q = prv[k]
                if prv[q] == 0:
                    prv[k] = 0
                else:
                    diff[k] = diff[q]
                    prv[k] = prv[q]
                par[q] = q+1
        if 2 <= j <= N-1:
            vv = M + R[j+1]
            if vv > best:
