        ranges=[]
        for i in range(N):
            ranges.append([u for u in range(0,U[i]+1) if 0<=H-u<=D[i]])
        # DP over sequences
        cur={u:0 for u in ranges[0]}
        for i in range(1,N):
            nxt={}
            for u in ranges[i]:
                c=[cur[p] for p in cur if abs(p-u)<=X]
                if c: nxt[u]=0
            cur=nxt
        if cur:
            cost=sum(U)+sum(D)-N*H
            if best is None or cost<best: best=cost
    return best

