    data = sys.stdin.read().split()
    N, M = int(data[0]), int(data[1])
    edges = []
    p = 2
    for _ in range(M):
        u = int(data[p]) - 1; v = int(data[p+1]) - 1; p += 2
        edges.append((u, v))
    adj = [0]*N
    for u, v in edges:
        adj[u] ^= 1 << v
        adj[v] ^= 1 << u
    rows = adj[:]
    piv = []
    r = 0
    for c in range(N):
        sel = None
        for i in range(r, N):
            if rows[i] >> c & 1:
                sel = i; break
        if sel is None:
            continue
        rows[r], rows[sel] = rows[sel], rows[r]
        for i in range(N):
            if i != r and rows[i] >> c & 1:
                rows[i] ^= rows[r]
        piv.append(c); r += 1
    pivset = set(piv)
    basis = []
    for f in range(N):
        if f in pivset:
            continue
        vec = 1 << f
        for i, c in enumerate(piv):
            if rows[i] >> f & 1:
                vec |= 1 << c
        basis.append(vec)
    X = []
    for v in range(N):
        x = 0
        for j, b in enumerate(basis):
            if b >> v & 1:
                x |= 1 << j
        if x == 0:
            print("No")
            return
        X.append(x)
    print("Yes")
    print(" ".join(map(str, X)))
