        nonlocal best
        best=max(best,k)
        idx=list(avail)
        for i in idx:
            for j in idx:
                if i!=j and 2*A[i]<=A[j]:
                    rec(avail-{i,j},k+1)
                    return
    # exhaustive over matchings
    def go(avail,k):
        nonlocal best
        best=max(best,k)
        if len(avail)<2: return
        av=sorted(avail)
        i=av[0]
        # either i unused
        go(avail-{i},k)
        for j in av[1:]:
            if 2*A[i]<=A[j]: go(avail-{i,j},k+1)
            if 2*A[j]<=A[i]: go(avail-{i,j},k+1)
