import math

def solve(N):
    d = 1
    while d*d*d < N and d <= 2*10**6:
        if N % d == 0:
            Q = N // d
            M = Q - d*d
            if M > 0 and M % 3 == 0:
                disc = 9*d*d + 12*M
                s = math.isqrt(disc)
                if s*s == disc and (s - 3*d) % 6 == 0:
                    y = (s - 3*d) // 6
                    if y >= 1:
                        return (y + d, y)
        d += 1
    return None

