class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        B = []; S = []
        for di,dj in dirs:
            Bd = [[0]*m for _ in range(n)]
            rows = range(n) if di == 1 else range(n-1,-1,-1)
            cols = range(m) if dj == 1 else range(m-1,-1,-1)
            for i in rows:
                gi = grid[i]; Bi = Bd[i]
                for j in cols:
                    v = gi[j]
                    if v == 1:
                        Bi[j] = 1
                    elif v == 0 or v == 2:
                        pi = i-di; pj = j-dj
                        if 0 <= pi < n and 0 <= pj < m:
                            pv = grid[pi][pj]; pb = Bd[pi][pj]
                            if pb > 0 and pv != v and (pv != 1 or v == 2):
                                Bi[j] = pb+1
            Sd = [[0]*m for _ in range(n)]
            for i in (range(n-1,-1,-1) if di == 1 else range(n)):
                gi = grid[i]; Si = Sd[i]
                for j in (range(m-1,-1,-1) if dj == 1 else range(m)):
                    v = gi[j]
                    if v == 0 or v == 2:
                        ni = i+di; nj = j+dj
                        add = 0
                        if 0 <= ni < n and 0 <= nj < m:
                            nv = grid[ni][nj]
                            if nv != v and (nv == 0 or nv == 2):
                                add = Sd[ni][nj]
                        Si[j] = 1+add
            B.append(Bd); S.append(Sd)
        best = 0
        for d in range(4):
            for i in range(n):
                for j in range(m):
                    L1 = B[d][i][j]
                    if L1 == 0: continue
                    if L1 > best: best = L1
                    d2 = (d+1) % 4
                    ni = i+dirs[d2][0]; nj = j+dirs[d2][1]
                    if 0 <= ni < n and 0 <= nj < m:
                        e = 2 if L1 % 2 == 1 else 0
                        if grid[ni][nj] == e:
                            t = L1 + S[d2][ni][nj]
                            if t > best: best = t
        return best

