from functools import lru_cache
from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def f(o, e, last):
            if o == 0 and e == 0:
                return 1
            res = 0
            if o > 0 and last != 0:
                res += o * f(o - 1, e, 0)
            if e > 0 and last != 1:
                res += e * f(o, e - 1, 1)
            return res
        O = (n + 1) // 2
        E = n // 2
        if k > f(O, E, 2):
            return []
        used = [False] * (n + 1)
        res = []
        co, ce, last = O, E, 2
        for _ in range(n):
            for x in range(1, n + 1):
                if used[x]:
                    continue
                ip = 0 if x % 2 == 1 else 1
                if last != 2 and ip == last:
                    continue
                no = co - (1 if ip == 0 else 0)
                ne = ce - (1 if ip == 1 else 0)
                cnt = f(no, ne, ip)
                if k <= cnt:
                    used[x] = True
                    res.append(x)
                    co, ce, last = no, ne, ip
                    break
                k -= cnt
        return res

