    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        p = [1 % k]
        for _ in range(n):
            p.append(p[-1] * 10 % k)
        w = []
        for i in range(h):
            j = n - 1 - i
            w.append(p[i] if i == j else (p[i] + p[j]) % k)
        reach = [None] * (h + 1)
        reach[h] = [False] * k
        reach[h][0] = True
        for i in range(h - 1, -1, -1):
            cur = [False] * k
            nxt = reach[i + 1]
            for d in (range(1, 10) if i == 0 else range(10)):
                c = d * w[i] % k
                for r in range(k):
                    if nxt[r]:
                        cur[(c + r) % k] = True
            reach[i] = cur
        if not reach[0][0]:
            return ""
        digits = []
        c0 = 0
        for i in range(h):
            for d in range(9, 0 if i == 0 else -1, -1):
                nc = (c0 + d * w[i]) % k
                if reach[i + 1][(-nc) % k]:
                    digits.append(d)
                    c0 = nc
                    break
        s = digits + digits[:n // 2][::-1]
        return ''.join(map(str, s))

