from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        a = nums; n = len(a)
        ng = [n]*n
        st = []
        for i in range(n):
            while st and a[st[-1]] < a[i]:
                ng[st.pop()] = i
            st.append(i)
        D = [0]*(n+1)
        for i in range(n-1, -1, -1):
            j = ng[i]
            D[i] = a[i]*(j-i) + (D[j] if j < n else 0)
        pre = [0]*(n+1)
        for i in range(n):
            pre[i+1] = pre[i] + a[i]
        sp = [list(range(n))]
        j = 1
        while (1 << j) <= n:
            prev = sp[-1]; h = 1 << (j-1)
            cur = []
            for i in range(n - (1 << j) + 1):
                x = prev[i]; y = prev[i+h]
                cur.append(x if a[x] >= a[y] else y)
            sp.append(cur)
            j += 1
        def argmax(l, r):
            t = (r-l+1).bit_length()-1
            x = sp[t][l]; y = sp[t][r-(1<<t)+1]
            return x if a[x] >= a[y] else y
        def cost(l, r):
            p = argmax(l, r)
            return (D[l]-D[p]) + a[p]*(r-p+1) - (pre[r+1]-pre[l])
        ans = 0
        r = 0
        for l in range(n):
            if r < l: r = l
            while r+1 < n and cost(l, r+1) <= k:
                r += 1
            ans += r-l+1
        return ans

