            k = pi[k - 1]
        if pat[q] == pat[k]:
            k += 1
        pi[q] = k
    res = []; k = 0
    for i, ch in enumerate(text):
        while k and ch != pat[k]:
            k = pi[k - 1]
        if ch == pat[k]:
            k += 1
        if k == m:
            res.append(i - m + 1)
            k = pi[k - 1]
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i1 = p.index('*'); i2 = p.index('*', i1 + 1)
        a = p[:i1]; b = p[i1 + 1:i2]; c = p[i2 + 1:]
        A = occ(s, a); B = occ(s, b); C = occ(s, c)
        if not A or not B or not C:
            return -1
        la = len(a); lb = len(b); lc = len(c)
        best = None
        for k in B:
            ai = bisect.bisect_right(A, k - la) - 1
            if ai < 0:
                continue
            ci = bisect.bisect_left(C, k + lb)
            if ci == len(C):
                continue
            L = C[ci] + lc - A[ai]
            if best is None or L < best:
                best = L
        return -1 if best is None else best

