import sys, heapq, random, itertools, time
import numpy as np
def solve(N, W, items):
    groups = {}
    for w, v in items:
        groups.setdefault(w, []).append(v)
    dp = np.zeros(W + 1, dtype=np.int64)
    for w, vs in groups.items():
        K = W // w
        heap = [(-(v - 1), idx, 1) for idx, v in enumerate(vs)]
        heapq.heapify(heap)
        gains = []
        vv = vs
        while heap and len(gains) < K:
            ng, idx, k = heapq.heappop(heap)
            g = -ng
            if g <= 0:
                break
            gains.append(g)
            heapq.heappush(heap, (-(vv[idx] - (2 * (k + 1) - 1)), idx, k + 1))
        if not gains:
            continue
        new = dp.copy()
        F = 0
        for c, g in enumerate(gains, 1):
            F += g
            s = c * w
            if s > W:
                break
            np.maximum(new[s:], dp[:W + 1 - s] + F, out=new[s:])
        dp = new
    return int(dp[W])

def main():
    data = sys.stdin.read().split()
    N, W = int(data[0]), int(data[1])
    items = [(int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(N)]
    print(solve(N, W, items))

def brute(N, W, items):
    best = 0
    ranges = [range(W // w + 1) for w, v in items]
    for ks in itertools.product(*ranges):
        if sum(k * items[i][0] for i, k in enumerate(ks)) <= W:
            best = max(best, sum(k * items[i][1] - k * k for i, k in enumerate(ks)))
    return best

