class Solution:
    def minOperations(self, n: int, m: int) -> int:
        LIM = 10000
        sieve = [True] * LIM
        sieve[0] = sieve[1] = False
        for i in range(2, int(LIM ** 0.5) + 1):
            if sieve[i]:
                for j in range(i * i, LIM, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        k = len(str(n))
        p = [10 ** i for i in range(k)]
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist.get(u, INF):
                continue
            if u == m:
                return d
            for i in range(k):
                digit = (u // p[i]) % 10
                for nd in (digit + 1, digit - 1):
                    if 0 <= nd <= 9:
                        v = u + (nd - digit) * p[i]
                        if sieve[v]:
                            continue
                        nc = d + v
                        if nc < dist.get(v, INF):
                            dist[v] = nc
                            heapq.heappush(pq, (nc, v))
        return -1

