def sol(W, blocks, queries):
    N = len(blocks)
    cols = [[] for _ in range(W + 1)]
    for i, (x, y) in enumerate(blocks):
        cols[x].append((y, i))
    for x in range(1, W + 1):
        cols[x].sort()
    K = min(len(cols[x]) for x in range(1, W + 1))
    idx = [0] * N
    for x in range(1, W + 1):
        for k, (y, i) in enumerate(cols[x]):
            idx[i] = k + 1
    R = [0] * (K + 1)
    for k in range(1, K + 1):
        M = max(cols[x][k - 1][0] for x in range(1, W + 1))
        R[k] = max(R[k - 1] + 1, M)
    out = []
    for T, A in queries:
        k = idx[A - 1]
        out.append(k > K or T < R[k])
    return out

