class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = [tuple(p) for p in points]
        n = len(pts)
        S = set(pts)
        best = -1
        for i in range(n):
            x1, y1 = pts[i]
            for j in range(n):
                x2, y2 = pts[j]
                if not (x1 < x2 and y1 < y2):
                    continue
                if (x1, y2) not in S or (x2, y1) not in S:
                    continue
                ok = True
                for k in range(n):
                    if k == i or k == j:
                        continue
                    qx, qy = pts[k]
                    if x1 <= qx <= x2 and y1 <= qy <= y2:
                        if (qx, qy) != (x1, y2) and (qx, qy) != (x2, y1):
                            ok = False
                            break
                if ok:
                    best = max(best, (x2 - x1) * (y2 - y1))
        return best

